      scan_va_copy_operator(&local_result, (an_operand*)NULL);
      break;

#if MICROSOFT_EXTENSIONS_ALLOWED
    case tok_uuidof:
      /* Microsoft __uuidof operation. */
      scan_uuidof_operator((a_rescan_control_block *)NULL,
                           &local_result, /*after_keyword=*/FALSE);
      break;
#endif /* MICROSOFT_EXTENSIONS_ALLOWED */

    case tok_dynamic_cast:
      /* dynamic_cast operation. */
      scan_dynamic_cast_operator((a_rescan_control_block *)NULL,
                                 &local_result);
      break;

    case tok_const_cast:
      /* const_cast operation. */
      scan_const_cast_operator((a_rescan_control_block *)NULL, &local_result);
      break;

    case tok_static_cast:
      /* static_cast operation. */
      scan_static_cast_operator((a_rescan_control_block *)NULL, &local_result);
      break;

#if MICROSOFT_EXTENSIONS_ALLOWED
    case tok_safe_cast:
      /* C++/CLI safe_cast operation. */
handle_safe_cast:
      scan_safe_cast_operator((a_rescan_control_block *)NULL, &local_result);
      break;
#endif /* MICROSOFT_EXTENSIONS_ALLOWED */

    case tok_reinterpret_cast:
      /* reinterpret_cast operation. */
      scan_reinterpret_cast_operator((a_rescan_control_block *)NULL,
                                     &local_result);
      break;

    case tok_intaddr:
      /* __INTADDR__ operation. */
      scan_intaddr_operator((a_rescan_control_block *)NULL, &local_result);
      break;
#if MICROSOFT_EXTENSIONS_ALLOWED
    case tok_gcnew:
#endif /* MICROSOFT_EXTENSIONS_ALLOWED */
    case tok_new:
scan_new:
      /* C++ "new" operator. */
      scan_new_operator((a_rescan_control_block *)NULL, &local_result);
      if (strict_ansi_mode) {
        /* The syntax does not allow a postfix-precedence operator following
           a new, e.g., new (double *)[17].  Give the syntax error only
           in strict mode. */
        if (!token_ends_expr(curr_token, PREC_PREFIX, local_options)) {
          expr_pos_diagnostic(strict_ansi_discretionary_severity,
                              ec_operator_not_allowed,
                              &pos_curr_token);
        }  /* if */
      }  /* if */
      break;
    case tok_delete:
scan_delete:
      /* C++ "delete" operator. */
      scan_delete_operator((a_rescan_control_block *)NULL, &local_result);
      break;
    case tok_lparen:
      /* This could be a cast operation or just an expression in
         parentheses. */
      /* Come here if a left parenthesis was trapped by the caller. */
handle_trapped_left_paren:
      scan_cast_or_expr(&local_result, &local_bound_function_selector,
                        local_options);
